SELECT ENAME, SAL,
       [ 함수 ] OVER (ORDER BY SAL DESC) AS RNK
FROM EMP;

SELECT DEPTNO, JOB, SUM(SAL)
FROM EMP
GROUP BY ROLLUP(DEPTNO, JOB);

SELECT ENAME, DEPTNO, SAL
FROM EMP
ORDER BY DEPTNO ASC, SAL DESC;

SELECT ENAME, SAL,
       LAG(SAL, 1) OVER (ORDER BY HIREDATE) AS PREV_SAL
FROM EMP;
